async function cdqOpenPdf(id){
  afficherMessage('Préparation du PDF…',true);
  try{
    const rec=await cdqLoadPdfRecord(id);
    if(!rec||!(rec.blob instanceof Blob)||!rec.blob.size)throw new Error('Le PDF reçu est invalide.');

    if(!window.__cdqPdfSaveBridgeV2304){
      window.__cdqPdfSaveBridgeV2304=true;
      window.addEventListener('message',async function(event){
        try{
          if(typeof cdqFromPwa==='function'&&!cdqFromPwa(event))return;
          const d=event.data||{};
          if(d.type!=='CDQ_PDF_SAVE_REQUEST_V2304')return;
          if(!(d.blob instanceof Blob)||!d.requestId||!d.fileId)return;

          try{
            const file=new File([d.blob],String(d.name||'Rapport.pdf'),{type:'application/pdf'});
            const action=await cdqImportPdf(String(d.fileId),file);
            const queued=(await cdqV19QueueGet()).some(function(x){return x.id===action.id;});
            cdqPostToPwa({
              type:'CDQ_PDF_SAVE_RESULT_V2304',
              requestId:String(d.requestId),
              ok:true,
              queued:queued
            });
          }catch(err){
            cdqPostToPwa({
              type:'CDQ_PDF_SAVE_RESULT_V2304',
              requestId:String(d.requestId),
              ok:false,
              error:err&&err.message?err.message:String(err)
            });
          }
        }catch(_){}
      });
    }

    const sent=typeof cdqPostToPwa==='function'&&cdqPostToPwa({
      type:'CDQ_OPEN_PDF_V2304',
      blob:rec.blob,
      name:String(rec.nom||'Rapport.pdf'),
      fileId:String(id||''),
      readOnly:String(utilisateurCourantRole||'')==='lecture'
    });

    if(!sent)throw new Error('Le lecteur PDF de l’application ne répond pas.');
    return true;
  }
  catch(e){afficherErreur(e);return false;}
}
